"use strict";(function(){function p(t){let e=(n,...i)=>l(o(t,n),n,...i).join("");return e.asArray=(n,...i)=>l(o(t,n),...i),e}function s(t){let e=(...n)=>l(t,...n).join("");return e.asArray=(...n)=>l(t,...n),e}function o(t,e){return t[i18n.quantity(e)]||t.other||t.one||""}function l(t,...e){let n=t.split(/(%(?:\d\$)?s)/);if(e.length){let i=n.indexOf("%s");if(i!=-1)n[i]=e[0];else for(let r=0;r<e.length;r++){let f=n.indexOf("%"+(r+1)+"$s");f!=-1&&(n[f]=e[r])}}return n}
let i=window.i18n.puzzleTheme={};i['advancedPawn']="ເບ້ທີ່ບຸກຂຶ້ນໜ້າ";i['advancedPawnDescription']="ມີເບ້ຂອງທ່ານໜຶ່ງຕົວເຂົ້າໄປເລິກໃນເຂດຂອງຄູ່ຕໍ່ສູ້, ອາດຈະກຳລັງຂົ່ມຂູ່ທີ່ຈະເລື່ອນຂັ້ນ.";i['advantage']="ຄວາມໄດ້ປຽບ";i['advantageDescription']="ຫາໂອກາດເພື່ອໃຫ້ໄດ້ປຽບຢ່າງເດັດຂາດ. (200cp ≤ eval ≤ 600cp)";i['anastasiaMate']="ການຈົນແບບ Anastasia";i['anastasiaMateDescription']="ມ້າ ແລະ ເຮືອ ຫຼື ຄອງ (Queen) ຮ່ວມມືກັນເພື່ອຈັບຄິງຂອງຄູ່ຕໍ່ສູ້ໄວ້ລະຫວ່າງຂອບກະດານ ແລະ ຕົວໝາກຂອງຝ່າຍນັ້ນເອງ.";i['arabianMate']="ການຈົນແບບອາຣັບ";i['arabianMateDescription']="ມ້າ ແລະ ເຮືອຮ່ວມມືກັນເພື່ອຈັບຄິງຂອງຄູ່ຕໍ່ສູ້ໄວ້ທີ່ມຸມຂອງກະດານ.";i['attackingF2F7']="ບຸກໂຈມຕີ f2 ຫຼື f7";i['attackingF2F7Description']="ການບຸກທີ່ເນັ້ນໃສ່ເບ້ f2 ຫຼື f7, ເຊັ່ນໃນຮູບແບບການເປີດ Fried Liver.";i['attraction']="ການດຶງດູດ (Attraction)";i['attractionDescription']="ການແແລກປ່ຽນ ຫຼື ການເສຍສະຫຼະເພື່ອຈູງໃຈ ຫຼື ບັງຄັບໃຫ້ຕົວໝາກຂອງຄູ່ຕໍ່ສູ້ໄປຫາຫ້ອງທີ່ສາມາດໃຊ້ແຜນການຕໍ່ໄປໄດ້.";i['backRankMate']="ການຈົນແຖວຫຼັງ";i['backRankMateDescription']="ຈົນຄິງຢູ່ແຖວຫຼັງສຸດ, ໃນຂະນະທີ່ມັນຖືກກັກຂັງໄວ້ໂດຍຕົວໝາກຂອງຝ່າຍມັນເອງ.";i['balestraMate']="ການຈົນແບບ Balestra";i['balestraMateDescription']="ບິຊອບ (Bishop) ເປັນຕົວທຳການຈົນ, ໃນຂະນະທີ່ຄອງ (Queen) ປິດທາງໜີທີ່ເຫຼືອທັງໝົດ.";i['bishopEndgame']="ເກມປາຍກະດານບິຊອບ";i['bishopEndgameDescription']="ການຫຼິ້ນປາຍກະດານທີ່ມີພຽງບິຊອບ (Bishop) ແລະ ເບ້.";i['blindSwineMate']="ການຈົນແບບ Blind Swine";i['blindSwineMateDescription']="ເຮືອສອງຕົວຮ່ວມມືກັນເພື່ອຈົນຄິງໃນພື້ນທີ່ 2x2 ຫ້ອງ.";i['bodenMate']="ການຈົນແບບ Boden";i['bodenMateDescription']="ບິຊອບ (Bishop) ສອງຕົວທີ່ບຸກໃນແນວສະຫຼຽງຕັດກັນ ທຳການຈົນຄິງທີ່ຖືກຕົວໝາກຝ່າຍດຽວກັນຂວາງທາງໄວ້.";i['capturingDefender']="ກິນຕົວປ້ອງກັນ";i['capturingDefenderDescription']="ການກຳຈັດຕົວໝາກທີ່ສຳຄັນໃນການປ້ອງກັນຕົວອື່ນ, ເພື່ອໃຫ້ສາມາດກິນຕົວໝາກທີ່ບໍ່ມີຕົວປ້ອງກັນນັ້ນໄດ້ໃນຕາຕໍ່ໄປ.";i['castling']="ການເຂົ້າປ້ອມ (Castling)";i['castlingDescription']="ນຳຄິງໄປຫາບ່ອນປອດໄພ ແລະ ກຽມເຮືອອອກບຸກໂຈມຕີ.";i['clearance']="ການເປີດທາງ (Clearance)";i['clearanceDescription']="ການເດີນໝາກເພື່ອເປີດຫ້ອງ, ແຖວ ຫຼື ແນວສະຫຼຽງ ສຳລັບແຜນການຕໍ່ໄປ.";i['collinearMove']="Collinear move";i['collinearMoveDescription']="Two opposing pieces face each other, and one slides along the line of attack without capturing the enemy piece.";i['cornerMate']="ການຈົນທີ່ມຸມກະດານ";i['cornerMateKnightDeliversDescription']="Confine the king to the corner using a rook or queen, and use a knight to deliver the checkmate.";i['crushing']="ການບຸກທະລາຍ (Crushing)";i['crushingDescription']="ສັງເກດເຫັນຄວາມຜິດພາດຂອງຄູ່ຕໍ່ສູ້ເພື່ອສ້າງຄວາມໄດ້ປຽບຢ່າງມະຫາສານ. (eval ≥ 600cp)";i['defensiveMove']="ການເດີນເພື່ອປ້ອງກັນ";i['defensiveMoveDescription']="ການເດີນໝາກທີ່ຊັດເຈນ ຫຼື ລຳດັບການເດີນທີ່ຈຳເປັນເພື່ອຫຼີກລ່ຽງການເສຍຕົວໝາກ ຫຼື ຄວາມໄດ້ປຽບ.";i['deflection']="ການເບນຄວາມສົນໃຈ (Deflection)";i['deflectionDescription']="ການເດີນໝາກເພື່ອດຶງຕົວໝາກຂອງຄູ່ຕໍ່ສູ້ອອກຈາກໜ້າທີ່ປ້ອງກັນ, ເຊັ່ນ: ການເຝົ້າຫ້ອງສຳຄັນ. ບາງຄັ້ງເອີ້ນວ່າ \"overloading\".";i['discoveredAttack']="ການເປີດບຸກ (Discovered attack)";i['discoveredAttackDescription']="ການເດີນຕົວໝາກ (ເຊັ່ນ: ມ້າ) ທີ່ເຄີຍຂວາງທາງການບຸກຂອງຕົວໝາກໄລຍະໄກ (ເຊັ່ນ: ເຮືອ) ອອກຈາກທາງ.";i['discoveredCheck']="ການເປີດຣຸກ (Discovered check)";i['discoveredCheckDescription']="ການເດີນຕົວໝາກຕົວໜຶ່ງເພື່ອເປີດການຣຸກຈາກຕົວໝາກອີກຕົວທີ່ຊ່ອນຢູ່ທາງຫຼັງ, ເຊິ່ງມັກຈະນຳໄປສູ່ຄວາມໄດ້ປຽບຢ່າງເດັດຂາດ.";i['doubleBishopMate']="ການຈົນດ້ວຍບິຊອບສອງຕົວ";i['doubleBishopMateDescription']="ບິຊອບ (Bishop) ສອງຕົວທີ່ບຸກໃນແນວສະຫຼຽງຂ້າງກັນ ທຳການຈົນຄິງທີ່ຖືກຕົວໝາກຝ່າຍດຽວກັນຂວາງທາງໄວ້.";i['doubleCheck']="ການຣຸກສອງທາງ (Double check)";i['doubleCheckDescription']="ການຣຸກດ້ວຍຕົວໝາກສອງຕົວພ້ອມກັນ ເຊິ່ງເປັນຜົນມາຈາກການເປີດຣຸກ ໂດຍທີ່ທັງຕົວທີ່ເດີນ ແລະ ຕົວທີ່ຖືກເປີດທາງນັ້ນຕ່າງກໍ່ບຸກຄິງຂອງຄູ່ຕໍ່ສູ້.";i['dovetailMate']="ການຈົນແບບ Dovetail";i['dovetailMateDescription']="ຄອງ (Queen) ທຳການຈົນຄິງທີ່ຢູ່ຕິດກັນ, ໂດຍທີ່ທາງໜີພຽງສອງທາງທີ່ເຫຼືອຂອງຄິງຖືກຕົວໝາກຝ່າຍດຽວກັນຂວາງໄວ້.";i['endgame']="ເກມປາຍກະດານ (Endgame)";i['endgameDescription']="ແຜນການໃນຊ່ວງສຸດທ້າຍຂອງເກມ.";i['enPassantAdjacentCaptureDescription']="A tactic involving the en passant rule, where a pawn can capture an opposing pawn that has just moved next to it with its initial two-square move.";i['epauletteMate']="Epaulette mate";i['epauletteMateDescription']="Two adjacent escape squares for a checked king are occupied by other pieces.";i['equality']="ຄວາມສະເໝີພາບ";i['equalityDescription']="ກັບຄືນມາຈາກສະຖານະການທີ່ເສຍປຽບ ເພື່ອຮັກສາຜົນສະເໝີ ຫຼື ເຮັດໃຫ້ຮູບເກມກັບມາສົມດຸນ. (eval ≤ 200cp)";i['exposedKing']="ຄິງທີ່ບໍ່ມີຕົວປ້ອງກັນ";i['exposedKingDescription']="ແຜນການທີ່ເນັ້ນໃສ່ຄິງທີ່ມີຕົວປ້ອງກັນໜ້ອຍ, ເຊິ່ງມັກຈະນຳໄປສູ່ການຈົນ.";i['fork']="ການແທງສອງທາງ (Fork)";i['forkOpposingPiecesDescription']="A move where a piece attacks two or more opposing pieces simultaneously.";i['hangingPiece']="ຕົວໝາກທີ່ຫຼຸດ (Hanging piece)";i['hangingPieceDescription']="ແຜນການທີ່ກ່ຽວຂ້ອງກັບຕົວໝາກຂອງຄູ່ຕໍ່ສູ້ທີ່ບໍ່ມີຕົວປ້ອງກັນ ຫຼື ມີຕົວປ້ອງກັນບໍ່ພຽງພໍ ຈົນສາມາດກິນໄດ້ຟຣີ.";i['hookMate']="ການຈົນແບບ Hook";i['hookMateOpposingPawnDescription']="Checkmate using a rook, knight, and pawn, where an opposing pawn blocks the king's escape.";i['interference']="ການຂັດຂວາງ (Interference)";i['interferenceDescription']="ການເດີນຕົວໝາກເຂົ້າແຊກກາງລະຫວ່າງຕົວໝາກສອງຕົວຂອງຄູ່ຕໍ່ສູ້ ເພື່ອເຮັດໃຫ້ຕົວໝາກເຫຼົ່ານັ້ນຂາດຕົວປ້ອງກັນ.";i['intermezzo']="ການເດີນແຊກ (Intermezzo)";i['intermezzoDescription']="ແທນທີ່ຈະເດີນຕາມທີ່ຄາດໄວ້, ແຕ່ກັບເດີນແຊກເພື່ອຂົ່ມຂູ່ຄູ່ຕໍ່ສູ້ກ່ອນ. ເອີ້ນອີກຢ່າງວ່າ \"Zwischenzug\".";i['killBoxMate']="ການຈົນແບບ Kill box";i['killBoxMateDescription']="ເຮືອຢູ່ຕິດກັບຄິງຂອງຄູ່ຕໍ່ສູ້ໂດຍມີຄອງ (Queen) ຄອຍສະໜັບສະໜູນ ແລະ ປິດທາງໜີ. ເຮືອ ແລະ ຄອງຈະກັກຄິງໄວ້ໃນພື້ນທີ່ 3x3 ທີ່ເອີ້ນວ່າ \"kill box\".";i['kingsideAttack']="ການບຸກຝັ່ງຄິງ (Kingside attack)";i['kingsideAttackDescription']="ການບຸກໂຈມຕີຄິງຂອງຄູ່ຕໍ່ສູ້ ຫຼັງຈາກທີ່ພວກເຂົາເຂົ້າປ້ອມທາງຝັ່ງຄິງ.";i['knightEndgame']="ເກມປາຍກະດານມ້າ";i['knightEndgameDescription']="ການຫຼິ້ນປາຍກະດານທີ່ມີພຽງມ້າ ແລະ ເບ້.";i['long']="ປິດສະໜາແບບຍາວ";i['longDescription']="ເດີນສາມຕາເພື່ອຊະນະ.";i['master']="ເກມລະດັບມາສເຕີ";i['masterDescription']="ປິດສະໜາຈາກເກມຂອງຜູ້ຫຼິ້ນທີ່ມີຕຳແໜ່ງ.";i['masterVsMaster']="ເກມລະດັບມາສເຕີ ພົບ ມາສເຕີ";i['masterVsMasterDescription']="ປິດສະໜາຈາກເກມລະຫວ່າງຜູ້ຫຼິ້ນທີ່ມີຕຳແໜ່ງສອງຄົນ.";i['mate']="ການຈົນ (Checkmate)";i['mateDescription']="ຊະນະເກມຢ່າງສວຍງາມ.";i['mateIn1']="ຈົນໃນ 1 ຕາ";i['mateIn1Description']="ທຳການຈົນໃນການເດີນພຽງຕາດຽວ.";i['mateIn2']="ຈົນໃນ 2 ຕາ";i['mateIn2Description']="ທຳການຈົນໃນສອງຕາ.";i['mateIn3']="ຈົນໃນ 3 ຕາ";i['mateIn3Description']="ທຳການຈົນໃນສາມຕາ.";i['mateIn4']="ຈົນໃນ 4 ຕາ";i['mateIn4Description']="ທຳການຈົນໃນສີ່ຕາ.";i['mateIn5']="ຈົນໃນ 5 ຕາ ຫຼື ຫຼາຍກວ່າ";i['mateIn5Description']="ຄິດຫາລຳດັບການຈົນແບບຍາວ.";i['middlegame']="ເກມກາງກະດານ";i['middlegameDescription']="ແຜນການໃນຊ່ວງທີສອງຂອງເກມ.";i['mix']="ຮູບແບບປະສົມ";i['mixDescription']="ມີທຸກຢ່າງປະປົນກັນ. ທ່ານຈະບໍ່ຮູ້ວ່າຈະເຈິຫຍັງ, ສະນັ້ນຈົ່ງກຽມພ້ອມຮັບມືກັບທຸກສະຖານະການ! ຄືກັນກັບການຫຼິ້ນແທ້.";i['morphyMateBishopAndRookDescription']="A bishop delivers checkmate to the king, while a rook helps confine it.";i['morphysMate']="ການຈົນແບບ Morphy";i['oneMove']="ປິດສະໜາແບບຕາດຽວ";i['oneMoveDescription']="ປິດສະໜາທີ່ມີຄວາມຍາວພຽງຕາດຽວ.";i['opening']="ການເປີດເກມ";i['openingDescription']="ແຜນການໃນຊ່ວງທຳອິດຂອງເກມ.";i['operaMate']="ການຈົນແບບ Opera";i['operaMateDescription']="ຣຸກຄິງດ້ວຍເຮືອ ແລະ ໃຊ້ບິຊອບ (Bishop) ເພື່ອປ້ອງກັນເຮືອ.";i['pawnEndgame']="ເກມປາຍກະດານເບ້";i['pawnEndgameDescription']="ການຫຼິ້ນປາຍກະດານທີ່ມີພຽງເບ້.";i['pillsburyMateRookAndBishopDescription']="A rook delivers checkmate to the king, while a bishop helps confine it.";i['pillsburysMate']="ການຈົນແບບ Pillsbury";i['pin']="ການປັກໝຸດ (Pin)";i['pinDescription']="ແຜນການປັກໝຸດ, ໂດຍທີ່ຕົວໝາກບໍ່ສາມາດເດີນໄດ້ ເພາະຈະເຮັດໃຫ້ຕົວໝາກທີ່ມີຄ່າສູງກວ່າທາງຫຼັງຖືກບຸກໂຈມຕີ.";i['playerGames']="ເກມຂອງຜູ້ຫຼິ້ນ";i['playerGamesDescription']="ຄົ້ນຫາປິດສະໜາທີ່ສ້າງຂຶ້ນຈາກເກມຂອງທ່ານ ຫຼື ຈາກເກມຂອງຜູ້ຫຼິ້ນຄົນອື່ນ.";i['promotePawnToQueenRookOrMinor']="Promote one of your pawns to a queen, rook or minor piece.";i['promotion']="ການເລື່ອນຂັ້ນ (Promotion)";i['puzzleDownloadInformation']=s("ປິດສະໜາເຫຼົ່ານີ້ແມ່ນເປັນສາທາລະນະ ແລະ ສາມາດດາວໂຫຼດໄດ້ຈາກ %s.");i['queenEndgame']="ເກມປາຍກະດານຄອງ";i['queenEndgameDescription']="ການຫຼິ້ນປາຍກະດານທີ່ມີພຽງຄອງ (Queen) ແລະ ເບ້.";i['queenRookEndgame']="ຄອງ ແລະ ເຮືອ";i['queenRookEndgameDescription']="ການຫຼິ້ນປາຍກະດານທີ່ມີພຽງຄອງ (Queen), ເຮືອ ແລະ ເບ້.";i['queensideAttack']="ການບຸກຝັ່ງຄອງ (Queenside attack)";i['queensideAttackDescription']="ການບຸກໂຈມຕີຄິງຂອງຄູ່ຕໍ່ສູ້ ຫຼັງຈາກທີ່ພວກເຂົາເຂົ້າປ້ອມທາງຝັ່ງຄອງ.";i['quietMove']="ການເດີນແບບງຽບໆ";i['quietMoveDescription']="ການເດີນໝາກທີ່ບໍ່ໄດ້ຣຸກ ຫຼື ກິນ, ແລະ ບໍ່ໄດ້ຂົ່ມຂູ່ຈະກິນໂດຍທັນທີ, ແຕ່ເປັນການກຽມແຜນການທີ່ຊ້ອນໄວ້ເພື່ອບຸກໃນຕາຕໍ່ໄປ.";i['rookEndgame']="ເກມປາຍກະດານເຮືອ";i['rookEndgameDescription']="ການຫຼິ້ນປາຍກະດານທີ່ມີພຽງເຮືອ ແລະ ເບ້.";i['sacrifice']="ການເສຍສະຫຼະ (Sacrifice)";i['sacrificeDescription']="ແຜນການທີ່ຍອມເສຍຕົວໝາກໃນໄລຍະສັ້ນ ເພື່ອກັບມາສ້າງຄວາມໄດ້ປຽບຫຼັງຈາກລຳດັບການເດີນໝາກທີ່ບັງຄັບໄວ້.";i['short']="ປິດສະໜາແບບສັ້ນ";i['shortDescription']="ເດີນສອງຕາເພື່ອຊະນະ.";i['skewer']="ການແທງທະລຸ (Skewer)";i['skewerDescription']="ແຜນການທີ່ບຸກໂຈມຕີຕົວໝາກທີ່ມີຄ່າສູງ ເພື່ອໃຫ້ມັນຫຼີກທາງແລ້ວກິນຕົວໝາກທີ່ມີຄ່າຕ່ຳກວ່າທາງຫຼັງ, ເຊິ່ງກົງກັນຂ້າມກັບການປັກໝຸດ.";i['smotheredMate']="ການຈົນແບບອັດຕັນ";i['smotheredMateDescription']="ການຈົນດ້ວຍມ້າ ໂດຍທີ່ຄິງບໍ່ສາມາດເດີນໄດ້ເພາະຖືກລ້ອມຮອບດ້ວຍຕົວໝາກຂອງຝ່າຍຕົນເອງ.";i['superGM']="ເກມລະດັບຊຸບເປີຈີເອັມ";i['superGMDescription']="ປິດສະໜາຈາກເກມຂອງຜູ້ຫຼິ້ນທີ່ເກັ່ງທີ່ສຸດໃນໂລກ.";i['swallowstailMate']="Swallow's tail mate";i['swallowstailMateDescription']="A checkmate pattern that visually resembles the appearance of a swallow’s tail, similar to a V shape.";i['trappedPiece']="ຕົວໝາກທີ່ຖືກກັບດັກ";i['trappedPieceDescription']="ຕົວໝາກທີ່ບໍ່ສາມາດໜີຈາກການຖືກກິນໄດ້ ເພາະມີຕາເດີນທີ່ຈຳກັດ.";i['triangleMate']="ການຈົນຮູບສາມຫຼ່ຽມ";i['triangleMateDescription']="ຄອງ (Queen) ແລະ ເຮືອ ຢູ່ຫ່າງຈາກຄິງຂອງຄູ່ຕໍ່ສູ້ໜຶ່ງຫ້ອງ ໂດຍຈັດວາງໃນຮູບແບບທີ່ສ້າງເປັນຮູບສາມຫຼ່ຽມ.";i['underPromotion']="ການເລື່ອນຂັ້ນແບບຮອງ";i['underPromotionDescription']="ການເລື່ອນຂັ້ນເປັນມ້າ, ບິຊອບ (Bishop) ຫຼື ເຮືອ.";i['veryLong']="ປິດສະໜາແບບຍາວຫຼາຍ";i['veryLongDescription']="ເດີນສີ່ຕາ ຫຼື ຫຼາຍກວ່າເພື່ອຊະນະ.";i['vukovicMate']="ການຈົນແບບ Vukovic";i['vukovicMateDescription']="ເຮືອ ແລະ ມ້າຮ່ວມມືກັນເພື່ອຈົນຄິງ. ເຮືອທຳການຈົນໂດຍມີຕົວໝາກຕົວທີສາມສະໜັບສະໜູນ ແລະ ໃຊ້ມ້າເພື່ອປິດທາງໜີ.";i['xRayAttack']="ການບຸກແບບເອັກຊະເລ (X-Ray attack)";i['xRayAttackDescription']="ການທີ່ຕົວໝາກບຸກ ຫຼື ປ້ອງກັນຫ້ອງໃດໜຶ່ງ ໂດຍຜ່ານຕົວໝາກຂອງຄູ່ຕໍ່ສູ້.";i['zugzwang']="ຊຸກສະວັງ (Zugzwang)";i['zugzwangDescription']="ຄູ່ຕໍ່ສູ້ມີຕາເດີນທີ່ຈຳກັດ ແລະ ທຸກໆຕາເດີນຈະເຮັດໃຫ້ສະຖານະການຂອງພວກເຂົາແຍ່ລົງ.";i['cornerMateDescription']="ກັກຄິງໄວ້ທີ່ມຸມກະດານໂດຍໃຊ້ເຮືອ ຫຼື ຄອງ (Queen) ແລະ ໃຊ້ມ້າເພື່ອທຳການຈົນ.";i['enPassantDescription']="ແຜນການທີ່ກ່ຽວຂ້ອງກັບກົດການກິນຜ່ານ (En passant), ໂດຍທີ່ເບ້ສາມາດກິນເບ້ຂອງຄູ່ຕໍ່ສູ້ທີ່ເດີນຂ້າມໄປສອງຫ້ອງໃນຕາທຳອິດ.";i['forkDescription']="ການເດີນຕົວໝາກຕົວດຽວເພື່ອບຸກໂຈມຕີຕົວໝາກຂອງຄູ່ຕໍ່ສູ້ສອງຕົວພ້ອມກັນ.";i['hookMateDescription']="ການຈົນດ້ວຍເຮືອ, ມ້າ ແລະ ເບ້ ໂດຍອາໄສເບ້ຂອງຄູ່ຕໍ່ສູ້ເພື່ອຈຳກັດທາງໜີຂອງຄິງ.";i['morphysMateDescription']="ໃຊ້ບິຊອບ (Bishop) ເພື່ອຣຸກຄິງ, ໃນຂະນະທີ່ເຮືອຊ່ວຍກັກທາງໜີໄວ້.";i['pillsburysMateDescription']="ເຮືອເປັນຕົວທຳການຈົນ, ໃນຂະນະທີ່ບິຊອບ (Bishop) ຊ່ວຍກັກຄິງໄວ້.";i['promotionDescription']="ເລື່ອນຂັ້ນເບ້ຂອງທ່ານໃຫ້ເປັນຄອງ (Queen) ຫຼື ຕົວໝາກຮອງ (Minor piece)."})()